import{_ as a,o as n,a as p,b as l}from"./app.DKoEZOcr.js";const c="/ascendc.github.io/pr/5487/assets/setflag_waitflag_multi_pipeline_sync.D0ek400o.png",h=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"同步控制","link":"/api/SIMD-API/basic_api/sync_control/sync_control"},{"text":"核内同步","link":"/api/SIMD-API/basic_api/sync_control/intra_core_sync/intra_core_sync"},{"text":"SetFlag/WaitFlag(ISASI)","link":"/api/SIMD-API/basic_api/sync_control/intra_core_sync/SetFlag_WaitFlag_ISASI"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/sync_control/intra_core_sync/SetFlag_WaitFlag_ISASI.md","filePath":"api/SIMD-API/basic_api/sync_control/intra_core_sync/SetFlag_WaitFlag_ISASI.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1788159000000}'),t={name:"api/SIMD-API/basic_api/sync_control/intra_core_sync/SetFlag_WaitFlag_ISASI.md"};function e(i,s,o,d,r,g){return n(),p("div",null,[...s[0]||(s[0]=[l('<div><article class="markdown-body"><h1>SetFlag/WaitFlag(ISASI)<span id="ZH-CN_TOPIC_0000001837467889"></span></h1><h2 id="产品支持情况">产品支持情况<span id="section1550532418810"></span><a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：支持</li></ul></div><div data-filter="x90"><ul><li>Kirin X90：支持</li></ul></div><div data-filter="9030"><ul><li>Kirin 9030：支持</li></ul></div><h2 id="功能说明">功能说明<span id="section618mcpsimp"></span><a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为：<code>&quot;basic_api/kernel_operator_block_sync_intf.h&quot;</code>。</p><p>如图1所示，SetFlag/WaitFlag接口用于核内多流水间的同步：</p><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><p>该接口标注为ISASI类别，不能保证跨硬件版本兼容。如需保证跨硬件版本兼容的同步控制接口，请参见<a href="SetFlag-WaitFlag.html">TQueSync SetFlag/WaitFlag</a>。二者的区别在于，TQueSync类接口可以保证跨硬件版本兼容。</p></div><ul><li>SetFlag：当源流水的前序指令的所有读写操作都完成之后，当前指令开始执行，并将硬件中的对应标志位设置为1。SetFlag只是设置硬件中的对应标志位，并不会阻塞源流水中的下一个指令。</li><li>WaitFlag：当目的流水执行到该指令时，如果发现硬件中对应标志位为0，目的流水的后续指令将一直被阻塞；如果发现硬件中对应标志位为1，则将硬件中对应标志位设置为0，同时目的流水的后续指令开始执行。</li></ul><p><strong>图1</strong> SetFlag/WaitFlag接口功能示意图<span id="zh-cn_topic_0000002511125384_fig58242463299"></span><br><img src="'+c+`" alt title="SetFlag_WaitFlag_多流水同步示意图"></p><h2 id="函数原型">函数原型<span id="section620mcpsimp"></span><a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="n">HardEvent</span><span class="w"> </span><span class="n">event</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">SetFlag</span><span class="p">(</span><span class="kt">int32_t</span><span class="w"> </span><span class="n">eventID</span><span class="p">)</span>
<span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="n">HardEvent</span><span class="w"> </span><span class="n">event</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">WaitFlag</span><span class="p">(</span><span class="kt">int32_t</span><span class="w"> </span><span class="n">eventID</span><span class="p">)</span>
</code></pre></div><h2 id="参数说明">参数说明<span id="section622mcpsimp"></span><a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 参数说明</p><table><thead><tr><th align="left">参数名</th><th align="left">输入/输出</th><th align="left">描述</th></tr></thead><tbody><tr><td align="left">event</td><td align="left">输入</td><td align="left">模板参数。同步事件，数据类型为HardEvent。同一核内的不同流水之间，在存在数据访问依赖时，需要根据数据访问的先后顺序，插入对应的同步事件。HardEvent用来表示对应的同步事件。<br>HardEvent命名规则为&lt;源流水_目标流水&gt;，其中源流水的指令先执行、目标流水中的指令后执行。例如MTE2_V，代表PIPE_MTE2为源流水，PIPE_V为目标流水，标识从PIPE_MTE2到PIPE_V的同步，PIPE_V等待PIPE_MTE2。<br>流水类型的取值及含义请参考<a href="intra_core_sync_overview.html#%E7%A1%AC%E4%BB%B6%E6%B5%81%E6%B0%B4%E7%B1%BB%E5%9E%8B">硬件流水类型</a>。由于硬件架构版本代际间的差异，不同硬件架构上的事件存在差异。HardEvent的取值范围请参考<a href="intra_core_sync_overview.html#%E6%A0%B8%E5%86%85%E5%90%8C%E6%AD%A5%E5%88%86%E7%B1%BB">核内同步分类小节中表2和表3</a>。</td></tr><tr><td align="left">eventID</td><td align="left">输入</td><td align="left">事件ID。数据类型为int32_t类型。eventID的取值范围与产品型号有关，具体请参考<a href="#section633mcpsimp">约束说明</a>。</td></tr></tbody></table><h2 id="返回值说明">返回值说明<span id="section640mcpsimp"></span><a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="约束说明">约束说明<span id="section633mcpsimp"></span><a class="header-anchor" href="#约束说明">​</a></h2><ul><li><p>SetFlag只是设置硬件标志位，不会阻塞源流水中的下一个指令。</p></li><li><p>SetFlag和WaitFlag必须成对使用，且SetFlag和WaitFlag的参数必须完全一致（包括模板参数event和输入参数eventID）。如果不匹配，会引发timeout问题。例如，<code>SetFlag&lt;HardEvent::S_MTE3&gt;(1)</code>和<code>WaitFlag&lt;HardEvent::MTE3_MTE1&gt;(1)</code>并不匹配，因为其模板参数event不同。</p></li><li><p>在采用<a href="../../../../../guide/programming_guide/programming_model/ai_core_simd_programming/tpipe_tque_programming/tpipe_tque_paradigm.html">TPipe-TQue框架编程范式</a>时，eventID需要通过<a href="../../resource_management/TPipe/AllocEventID.html">AllocEventID</a>或者<a href="../../resource_management/TPipe/FetchEventID.html">FetchEventID</a>来获取。</p></li><li><p>在采用<a href="../../../../../guide/programming_guide/programming_model/ai_core_simd_programming/cpp_tensor_programming/static_tensor_programming.html">静态Tensor编程范式</a>时，事件的类型和事件ID由开发者自行管理，建议使用事件ID0-5，事件ID6用于系统内部规划（当前未使用），事件ID7用于TPipe编程中的<strong>自动同步</strong>功能，目前暂不建议直接使用事件ID6-7。</p></li><li><p>eventID的取值范围如下：</p><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT，数据范围为：0-7。</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品，数据范围为：0-7。</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品，数据范围为：0-7。</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core，数据范围为：0-7。</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品，数据范围为：0-3。</li></ul></div></li><li><p>相同流水、相同eventID下，连续使用SetFlag会引发未定义行为，此时再执行PipeBarrier&lt;PIPE_ALL&gt;会出现卡死现象：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">AscendC</span><span class="o">::</span><span class="n">SetFlag</span><span class="o">&lt;</span><span class="n">AscendC</span><span class="o">::</span><span class="n">HardEvent</span><span class="o">::</span><span class="n">M_MTE1</span><span class="o">&gt;</span><span class="p">(</span><span class="mi">0</span><span class="p">);</span><span class="w">  </span><span class="c1">// 第一次调用SetFlag。</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">SetFlag</span><span class="o">&lt;</span><span class="n">AscendC</span><span class="o">::</span><span class="n">HardEvent</span><span class="o">::</span><span class="n">M_MTE1</span><span class="o">&gt;</span><span class="p">(</span><span class="mi">0</span><span class="p">);</span><span class="w">  </span><span class="c1">// 第二次调用SetFlag（相同流水、相同eventID连续使用，引发未定义行为）。</span>
<span class="p">...</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">PipeBarrier</span><span class="o">&lt;</span><span class="n">PIPE_ALL</span><span class="o">&gt;</span><span class="p">();</span><span class="w">  </span><span class="c1">// 触发卡死。</span>
<span class="p">...</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">WaitFlag</span><span class="o">&lt;</span><span class="n">AscendC</span><span class="o">::</span><span class="n">HardEvent</span><span class="o">::</span><span class="n">M_MTE1</span><span class="o">&gt;</span><span class="p">(</span><span class="mi">0</span><span class="p">);</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">WaitFlag</span><span class="o">&lt;</span><span class="n">AscendC</span><span class="o">::</span><span class="n">HardEvent</span><span class="o">::</span><span class="n">M_MTE1</span><span class="o">&gt;</span><span class="p">(</span><span class="mi">0</span><span class="p">);</span>
</code></pre></div></li></ul><h2 id="调用示例">调用示例<span id="section837496171220"></span><a class="header-anchor" href="#调用示例">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">AscendC</span><span class="o">::</span><span class="n">DataCopy</span><span class="p">(</span><span class="n">src1Local</span><span class="p">,</span><span class="w"> </span><span class="n">src1Global</span><span class="p">[</span><span class="n">i</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">tileLength</span><span class="p">],</span><span class="w"> </span><span class="n">tileLength</span><span class="p">);</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">DataCopy</span><span class="p">(</span><span class="n">src0Local</span><span class="p">,</span><span class="w"> </span><span class="n">src0Global</span><span class="p">[</span><span class="n">i</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">tileLength</span><span class="p">],</span><span class="w"> </span><span class="n">tileLength</span><span class="p">);</span>

<span class="c1">// 循环内依赖：先“DataCopy(PIPE_MTE2)写src0Local”，后“Maxs和Mins（PIPE_V）读src0Local”。</span>
<span class="c1">// 由于PIPE_V需要等待PIPE_MTE2，所以需要插入以下同步。</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">SetFlag</span><span class="o">&lt;</span><span class="n">AscendC</span><span class="o">::</span><span class="n">HardEvent</span><span class="o">::</span><span class="n">MTE2_V</span><span class="o">&gt;</span><span class="p">(</span><span class="n">EVENT_ID0</span><span class="p">);</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">WaitFlag</span><span class="o">&lt;</span><span class="n">AscendC</span><span class="o">::</span><span class="n">HardEvent</span><span class="o">::</span><span class="n">MTE2_V</span><span class="o">&gt;</span><span class="p">(</span><span class="n">EVENT_ID0</span><span class="p">);</span>

<span class="n">AscendC</span><span class="o">::</span><span class="n">Maxs</span><span class="p">(</span><span class="n">tmpTensor1</span><span class="p">,</span><span class="w"> </span><span class="n">src0Local</span><span class="p">,</span><span class="w"> </span><span class="n">inputVal</span><span class="p">,</span><span class="w"> </span><span class="n">tileLength</span><span class="p">);</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">Mins</span><span class="p">(</span><span class="n">tmpTensor2</span><span class="p">,</span><span class="w"> </span><span class="n">src0Local</span><span class="p">,</span><span class="w"> </span><span class="n">inputVal</span><span class="p">,</span><span class="w"> </span><span class="n">tileLength</span><span class="p">);</span>
</code></pre></div></article></div>`,1)])])}const v=a(t,[["render",e]]);export{h as __pageData,v as default};
